using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ReliefAfflictionRuinCustomTag", menuName = "Data/Battle/Battle Actions/Tags/ReliefAfflictionRuinCustomTag", order = 0)]
public class ReliefAfflictionRuinCustomTag : CreatureWithEffectCustomTag
{
	[SerializeField]
	private bool thenDecreaseEffect;

	[SerializeField]
	[ShowIf("thenDecreaseEffect")]
	private Effect effectToDecrease;

	[SerializeField]
	private bool ruin;

	public override string GetTagDescription()
	{
		string format = (thenDecreaseEffect ? ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("CreatureWithEffectThenDecreaseEffect") : GetCreatureWithEffectDescription());
		string text = (thenDecreaseEffect ? ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedThenDecreaseEffect(effectToDecrease, 1) : "");
		string str = (ruin ? ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedAtTheStartOfTheirTurn() : ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedAtTheEndOfTheirTurn());
		return Smart.Format(format, GetTagName(), GetPurifyCorruptName(), str.LowercaseFirst().RemoveLast(), text);
	}
}
